# Try: only fill the 1 minority cell if 3/4 are the same

def apply_2x2_single_fill(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h-1):
        for c in range(w-1):
            vals = [grid[r][c], grid[r][c+1], grid[r+1][c], grid[r+1][c+1]]
            from collections import Counter
            cnt = Counter(vals)
            # Check if exactly 3 same, 1 different
            counts = list(cnt.values())
            if 3 in counts and 1 in counts:
                # Most common value fills the lone different cell
                majority = [v for v, c in cnt.items() if c == 3][0]
                minority = [v for v, c in cnt.items() if c == 1][0]
                # Find which position has the minority
